  apiSecretKey: process.env.SHOPIFY_API_SECRET || "",
  apiVersion: ApiVersion.July26,
  scopes: process.env.SCOPES?.split(","),
  appUrl: process.env.SHOPIFY_APP_URL || "",
  authPathPrefix: "/auth",
  sessionStorage: new PrismaSessionStorage(prisma),
  distribution: AppDistribution.AppStore,
  billing: { /* Basic e Pro, ver etapa de cobrança */ },
  hooks: {
    afterAuth: async ({ session }) => {
      shopify.registerWebhooks({ session });
    },
  },
  future: {
    unstable_newEmbeddedAuthStrategy: true, // session tokens + token exchange
    // Apps públicos novos só podem usar tokens offline que expiram; tokens sem
    // expiração recebem 403 da Admin API. A lib renova o token sozinha.
    expiringOfflineAccessTokens: true,
  },
});

/**
 * Texto legível de um erro da Admin API. A lib lança um Response (com o corpo
 * de erro da Shopify) em vez de um Error; aqui lemos esse corpo.
 */
export async function describeError(error) {
  if (error instanceof Response) {
    let body = "";
    try {
      body = await error.clone().text();
    } catch (e) {
      /* corpo já consumido */
    }
    return `HTTP ${error.status} ${body}`.trim();
  }
  // HttpResponseError da @shopify/shopify-api (ex.: billing.check)
  if (error?.response?.body) {
    return `HTTP ${error.response.code} ${JSON.stringify(error.response.body)}`;
  }
  return error?.message ?? String(error);
}

// 1ª tentativa (não bastou): apagar a sessão antiga e autenticar de novo.
// Funciona para o app, mas o token antigo continua válido na Shopify
// e o Partner Dashboard mostra "Deprecated offline token".
async function authenticateAdmin(request) {
  const context = await shopify.authenticate.admin(request);
  const { session } = context;
  if (!session.isOnline && !session.expires) {
    await shopify.sessionStorage.deleteSession(session.id);
    return shopify.authenticate.admin(request);
  }
  return context;
}

// app/models/offline-tokens.server.js
async function exchangeLegacyToken(shop, accessToken) {
  const response = await fetch(`https://${shop}/admin/oauth/access_token`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json" },
    body: JSON.stringify({
      client_id: process.env.SHOPIFY_API_KEY,
      client_secret: process.env.SHOPIFY_API_SECRET,
      grant_type: "urn:ietf:params:oauth:grant-type:token-exchange",
      subject_token: accessToken,
      subject_token_type: "urn:shopify:params:oauth:token-type:offline-access-token",
      requested_token_type: "urn:shopify:params:oauth:token-type:offline-access-token",
      expiring: "1",
    }),
  });
  if (!response.ok) throw new Error(`token exchange respondeu ${response.status}`);
  return response.json();
}

export const isLegacyOfflineSession = (session) => !session.isOnline && !session.expires;

export async function migrateLegacyOfflineSession(session) {
  const token = await exchangeLegacyToken(session.shop, session.accessToken);
  if (!token.expires_in) throw new Error("token exchange não devolveu um token que expira");
  await prisma.session.update({
    where: { id: session.id },
    data: {
      accessToken: token.access_token,
      scope: token.scope,
      expires: secondsFromNow(token.expires_in),
      refreshToken: token.refresh_token ?? null,
      refreshTokenExpires: token.refresh_token_expires_in
        ? secondsFromNow(token.refresh_token_expires_in)
        : null,
    },
  });
}

/** Migra todas as lojas de uma vez; roda ao subir o servidor. */
export async function migrateAllLegacyOfflineSessions() {
  const legacy = await prisma.session.findMany({ where: { isOnline: false, expires: null } });
  for (const session of legacy) {
    try {
      await migrateLegacyOfflineSession(session);
    } catch (error) {
      console.error(`[offline-tokens] falha ao migrar ${session.shop}: ${error.message}`);
    }
  }
}

// app/shopify.server.js
async function authenticateAdmin(request) {
  const context = await shopify.authenticate.admin(request);
  const { session } = context;
  if (isLegacyOfflineSession(session)) {
    try {
      await migrateLegacyOfflineSession(session);
    } catch (error) {
      console.error(`[offline-tokens] falha ao migrar ${session.shop}: ${error.message}`);
      await shopify.sessionStorage.deleteSession(session.id);
    }
    return shopify.authenticate.admin(request);
  }
  return context;
}

// lojas que não abrirem o app também precisam migrar
migrateAllLegacyOfflineSessions().catch((error) =>
  console.error(`[offline-tokens] migração em lote falhou: ${error.message}`),
);

export const authenticate = { ...shopify.authenticate, admin: authenticateAdmin };

/**
 * Webhooks que não chamam a Admin API (desinstalação e compliance). O
 * authenticate.webhook da lib carrega e renova o token offline da loja; depois
 * da desinstalação a renovação é recusada e a lib responde 500.
 * Aqui só validamos a assinatura HMAC.
 */
export async function verifyWebhook(request) {
  if (request.method !== "POST") {
    throw new Response(undefined, { status: 405 });
  }
  const rawBody = await request.text();
  const received = Buffer.from(request.headers.get("X-Shopify-Hmac-Sha256") || "");
  const expected = Buffer.from(
    crypto
      .createHmac("sha256", process.env.SHOPIFY_API_SECRET || "")
      .update(rawBody, "utf8")
      .digest("base64"),
  );
  if (received.length !== expected.length || !crypto.timingSafeEqual(received, expected)) {
    throw new Response(undefined, { status: 401 });
  }

  const shop = request.headers.get("X-Shopify-Shop-Domain");
  // "shop/redact" -> "SHOP_REDACT", mesmo formato do topic da lib
  const topic = (request.headers.get("X-Shopify-Topic") || "").toUpperCase().replace(/[/.]/g, "_");
  if (!shop || !topic) {
    throw new Response(undefined, { status: 400 });
  }
  return { shop, topic, payload: JSON.parse(rawBody || "{}") };
}

// app/routes/webhooks.app.uninstalled.jsx
import { verifyWebhook } from "../shopify.server";
import prisma from "../db.server";

export const action = async ({ request }) => {
  const { shop } = await verifyWebhook(request);

  await prisma.session.deleteMany({ where: { shop } });
  await prisma.flag.deleteMany({ where: { shop } });
  await prisma.shopSettings.deleteMany({ where: { shop } });

  return new Response();
};

// app/routes/webhooks.compliance.jsx
// O app não guarda dados de clientes (só flags e configurações da loja).
export const action = async ({ request }) => {
  const { shop, topic } = await verifyWebhook(request);

  switch (topic) {
    case "CUSTOMERS_DATA_REQUEST":
    case "CUSTOMERS_REDACT":
      console.log(`[compliance] ${topic} de ${shop}: nenhum dado de cliente armazenado.`);
      break;
    case "SHOP_REDACT": // 48h depois da desinstalação
      await prisma.$transaction([
        prisma.flag.deleteMany({ where: { shop } }),
        prisma.shopSettings.deleteMany({ where: { shop } }),
        prisma.session.deleteMany({ where: { shop } }),
      ]);
      console.log(`[compliance] SHOP_REDACT: dados de ${shop} apagados.`);
      break;
    default:
      return new Response("Tópico não tratado", { status: 404 });
  }
  return new Response();
};

